# owner: platform
import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


# ---
def shift(worker: str, start: int, end: int) -> Shift:
    return Shift(worker, "mon", Span(start, end))


class TimesheetLineTests(unittest.TestCase):
    def test_busiest_first_with_hours(self):
        shifts = [
            shift("Odell", 540, 810),
            shift("Brisa", 540, 1020),
            shift("Brisa", 540, 1020),
            shift("Quill", 540, 870),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 16.0 hours",
                "Quill: 1 shift, 5.5 hours",
                "Odell: 1 shift, 4.5 hours",
            ],
        )

    def test_ties_sorted_by_name(self):
        shifts = [
            shift("Quill", 540, 600),
            shift("Brisa", 540, 600),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 1 shift, 1.0 hours",
                "Quill: 1 shift, 1.0 hours",
            ],
        )

    def test_hours_round_to_one_decimal(self):
        line = timesheet_lines([shift("Brisa", 0, 100)])[0]
        self.assertEqual(line, "Brisa: 1 shift, 1.7 hours")

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            blank = shift(name, 540, 600)
            with self.subTest(name=name):
                with self.assertRaises(ProjectError):
                    timesheet_lines([blank])
